def test_a_day_of_mixed_web_and_mcp_use_shows_per_user_and_per_tool(
    client: TestClient, tenant_a: Tenant, tenant_b: Tenant
) -> None:
    mixed_day(client, tenant_a, tenant_b)

    response = client.get("/admin/usage", headers=tenant_a.headers())

    assert response.status_code == 200
    report = response.json()
    (today,) = report["days"]
    assert today["day"] == datetime.now(UTC).date().isoformat()
    assert today["active_users"] == 2
    assert today["requests_by_owner"] == {str(tenant_a.owner_id): 3, str(tenant_b.owner_id): 2}
    assert today["requests_by_client"] == {"web": 2, "mcp": 3}
    assert today["tools_by_count"] == {"find_person": 2, "log_interaction": 1}
    assert today["entity_pages_by_count"] == [
        {"entity_type": "people", "entity_id": str(tenant_a.row_id(Person)), "views": 2}
    ]
    assert {row["owner_id"] for row in report["rows"]} == {
        str(tenant_a.owner_id),
        str(tenant_b.owner_id),
    }
    assert len(report["rows"]) == 5

def test_every_table_has_row_level_security_and_a_tenant_policy(db_session: Session) -> None:
    tables = db_session.execute(
        text(
            "SELECT c.relname, c.relrowsecurity, pg_get_userbyid(c.relowner) AS owner "
            "FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace "
            "WHERE n.nspname = 'public' AND c.relkind = 'r'"
        )
    ).all()
    policies = {
        (row.tablename, row.policyname): row
        for row in db_session.execute(text("SELECT * FROM pg_policies"))
    }

    names = {t.relname for t in tables} - NON_MODEL_TABLES
    assert names == {table.name for table in TABLES.values()}
    for table in tables:
        if table.relname in NON_MODEL_TABLES:
            continue
        assert table.relrowsecurity, table.relname
        assert table.owner != APP_ROLE, table.relname
        policy = policies[(table.relname, "tenant")]
        assert policy.roles == [APP_ROLE]
        assert f"{owner_column(table.relname)} = current_owner_id()" in policy.qual
        assert f"{owner_column(table.relname)} = current_owner_id()" in policy.with_check

def test_no_request_body_is_recorded(
    client: TestClient, db_session: Session, tenant_a: Tenant
) -> None:
    headers = tenant_a.headers() | {"If-Match": '"1"'}

    response = client.patch("/me", json={"display_name": "Body-Marker"}, headers=headers)

    assert response.status_code == 200
    assert "Body-Marker" not in repr(only_row(db_session))

